from fixtures import Fixture, load_fixtures, ROWS
from ordering import ranked_codes


def test_nine_before_ten():
    assert ranked_codes([Fixture("a", 10), Fixture("b", 9)]) == ["9", "10"]


def test_mixed_lengths():
    assert ranked_codes([Fixture("a", 100), Fixture("b", 25), Fixture("c", 9), Fixture("d", 1000)]) == ["9", "25", "100", "1000"]


def test_stored():
    assert ranked_codes(list(load_fixtures())) == [str(v) for v in sorted(v for _, v in ROWS)]


def test_codes_are_text():
    assert all(isinstance(c, str) for c in ranked_codes(list(load_fixtures())))


def test_empty():
    assert ranked_codes([]) == []

